for a, t in ((2.0, 30), (0.5, 60), (3.0, 20)):
    v, s = A.speed(a, t), A.dist(a, t)
    X('irs', 3, f'Máy bay có gia tốc không đổi {a:g} m/s² dọc đường bay trong {t} s, xuất phát từ vận tốc 0. IRS tích phân hai lần sẽ cho vận tốc và quãng đường là:', f'An aircraft accelerates at a constant {a:g} m/s² along its track for {t} s, starting from rest. An IRS integrating twice gives a velocity and a distance of:',
      [(f'{v:g} m/s; {s:g} m', f'{v:g} m/s; {s:g} m'), (f'{v:g} m/s; {v * t:g} m', f'{v:g} m/s; {v * t:g} m'), (f'{v / 2:g} m/s; {s:g} m', f'{v / 2:g} m/s; {s:g} m'), (f'{a * t * t:g} m/s; {s / 2:g} m', f'{a * t * t:g} m/s; {s / 2:g} m')], 0,
      f'$v=at={a:g}\\times{t}={v:g}$ m/s; $s=\\tfrac12at^2={s:g}$ m (không phải $vt={v * t:g}$ m vì vận tốc tăng dần).', f'$v=at={a:g}\\times{t}={v:g}$ m/s; $s=\\tfrac12at^2={s:g}$ m (not $vt={v * t:g}$ m because the speed grows steadily).', 'Tích phân gia tốc', 'Integrating acceleration')
X('irs', 2, 'Hệ quán tính có bệ con quay gắn trên khung gimbal (gimballed) có nhược điểm nào so với hệ gắn cứng (strap-down)?', 'Which drawback does a gimballed inertial system have compared with a strap-down system?',
  [('dễ "khoá" hoặc "lật" khi cơ động mạnh và phụ thuộc cơ cấu chuyển động', 'it can "lock up" or "topple" in violent manoeuvres and depends on moving parts'), ('sai số cao hơn vì cả ba gia tốc kế đo trọng lực', 'higher error because all three accelerometers measure gravity'), ('phải gắn cố định vào cấu trúc máy bay', 'it must be fixed to the aircraft structure')], 0, 'Ưu điểm của gimballed là sai số vốn thấp hơn và đơn giản (Tooley 15.7.1).', 'The advantages of gimballed are inherently lower error and simplicity (Tooley 15.7.1).', 'Gimballed so với strap-down', 'Gimballed versus strap-down')
X('irs', 2, 'Trong hệ gắn cứng (strap-down) con quay và gia tốc kế:', 'In a strap-down system the gyros and accelerometers:', [('gắn vào cấu trúc máy bay và đo tốc độ góc và gia tốc theo các trục gắn với máy bay', 'are fixed to the aircraft structure and sense angular rate and acceleration about the aircraft axes'), ('nằm trên bệ luôn giữ hướng cố định', 'sit on a platform that keeps a fixed orientation'), ('chỉ dùng được ở mặt đất', 'only work on the ground')], 0, 'Tooley 15.7.2: khung quy chiếu chuyển động.', 'Tooley 15.7.2: a moving frame of reference.', 'Strap-down', 'Strap-down')
X('irs', 2, 'Vì sao IRS cần quá trình khởi tạo (căn chỉnh) trước chuyến bay?', 'Why does an IRS need initialisation (alignment) before flight?', [('để có mốc chuẩn: con quay chạy tới tốc độ, hướng la bàn được căn và toạ độ xuất phát được nhập', 'to give a datum: the gyros run up, the compass heading is aligned and the origin latitude and longitude are entered'), ('để nạp cơ sở dữ liệu 28 ngày', 'to load the 28-day database'), ('để tắt GPS', 'to switch off GPS')], 0, 'Tooley 15.7.', 'Tooley 15.7.', 'Khởi tạo IRS', 'IRS initialisation')
X('tcas', 1, 'TCAS là loại hệ thống nào?', 'What kind of system is TCAS?', [('hệ thống giám sát và tránh va chạm, một dạng radar thứ cấp', 'a surveillance and avoidance system, a secondary radar facility'), ('hệ thống hạ cánh bằng thiết bị', 'an instrument landing system'), ('hệ thống thông tin dữ liệu', 'a data communication system')], 0, 'Tooley 15.8.', 'Tooley 15.8.', 'TCAS là gì', 'What TCAS is')
X('tcas', 2, 'TCAS cung cấp hướng dẫn tránh va chạm theo:', 'TCAS provides collision-avoidance guidance in:', [('chiều thẳng đứng, không có hướng dẫn theo chiều ngang', 'the vertical sense only, no lateral guidance'), ('cả chiều ngang và thẳng đứng', 'both lateral and vertical'), ('chỉ chiều ngang', 'the lateral sense only')], 0, 'Tooley 15.8.', 'Tooley 15.8.', 'TCAS: chiều hướng dẫn', 'TCAS: guidance sense')
X('tcas', 2, 'Biến số quan trọng nhất để TCAS dự đoán va chạm là:', 'The most important variable for TCAS collision prediction is:', [('tốc độ tiếp cận (closure rate)', 'the closure rate'), ('hướng bay (heading) của máy bay kia', 'the other aircraft\'s heading'), ('màu sơn máy bay', 'the colour of the aircraft')], 0, 'Tooley 15.8: không cần thông tin hướng hay phương vị để tính cảnh báo TCAS.', 'Tooley 15.8: heading or bearing is not needed to compute a TCAS alarm.', 'TCAS: tốc độ tiếp cận', 'TCAS: closure rate')
for d, v in ((10, 600), (4, 480), (6, 360), (2.5, 300)):
    t = A.tau(d, v)
    X('tcas', 2 if d != 2.5 else 3, f'Máy bay lạ cách {d:g} NM và đang tiến lại gần với tốc độ tiếp cận {v} kt. Thời gian tới điểm tiếp cận gần nhất (khoảng cách chia tốc độ tiếp cận) là:', f'An intruder is {d:g} NM away and closing at {v} kt. The time to the closest point of approach (distance divided by closure rate) is:',
      [(f'{t:g} s', f'{t:g} s'), (f'{t / 60:g} s', f'{t / 60:g} s'), (f'{d / v:g} s', f'{d / v:g} s'), (f'{t * 2:g} s', f'{t * 2:g} s')], 0, f'$\\tau={d:g}/{v}\\text{{ h}}={t:g}$ s ({d:g} NM / {v} kt × 3600 s/h).', f'$\\tau={d:g}/{v}\\text{{ h}}={t:g}$ s ({d:g} NM / {v} kt × 3600 s/h).', 'Thời gian tới CPA', 'Time to CPA')
X('tcas', 2, 'Cảnh báo giao thông (TA) của TCAS thể hiện trên ND bằng:', 'A TCAS traffic advisory (TA) is shown on the ND as:', [('chữ TRAFFIC màu vàng và thông báo thoại "traffic, traffic"', 'the word TRAFFIC in yellow and the voice call "traffic, traffic"'), ('chữ TRAFFIC màu đỏ và lệnh bổ nhào', 'the word TRAFFIC in red and a pitch command'), ('đèn xanh và chuông', 'a green light and a bell')], 0, 'TA là mức cảnh báo thấp hơn, chỉ để lưu ý một xung đột tiềm tàng (Tooley 15.8).', 'A TA is the lower alert level, only to draw attention to a potential conflict (Tooley 15.8).', 'TCAS: TA', 'TCAS: TA')
X('tcas', 2, 'Khuyến cáo xử lý (RA) của TCAS khác TA ở chỗ:', 'A TCAS resolution advisory (RA) differs from a TA in that it:', [('là mức cảnh báo cao nhất, kèm lệnh cao độ bằng âm thanh và hình ảnh; phi công phải tắt lái tự động và bay tay', 'is the highest alert level with aural and visual pitch commands; the pilot must disengage the autopilot and fly manually'), ('chỉ hiện chữ vàng', 'only shows yellow text'), ('chỉ xuất hiện khi mặt đất yêu cầu', 'only appears when ground control asks')], 0, 'Tooley 15.8: lệnh cao độ của RA có ưu tiên cao nhất; không có dữ liệu độ cao của đối phương thì RA sẽ không xảy ra.', 'Tooley 15.8: the RA pitch command has the highest priority; without altitude data from the target an RA will not occur.', 'TCAS: RA', 'TCAS: RA')
X('tcas', 2, 'Nếu máy bay lạ không cung cấp dữ liệu độ cao, TCAS giả định độ cao tương đối của nó nằm trong khoảng:', 'If the intruder provides no altitude data, TCAS assumes its relative altitude is within:', [('1 200 ft', '1,200 ft'), ('120 ft', '120 ft'), ('12 000 ft', '12,000 ft')], 0, 'Tooley 15.8.', 'Tooley 15.8.', 'TCAS: giả định độ cao', 'TCAS: altitude assumption')
X('tcas', 2, 'TCAS cần cảm biến vị trí càng hạ cánh vì:', 'TCAS needs the landing-gear position sensors because:', [('càng hạ làm nhiễu ăng ten định hướng phía dưới nên phải chặn việc phát hiện máy bay bay bên dưới', 'the extended gear disturbs the lower directional antenna, so detection of traffic below must be inhibited'), ('càng hạ làm máy bay nặng hơn', 'the extended gear makes the aircraft heavier'), ('càng hạ tắt bộ phát đáp', 'the extended gear switches off the transponder')], 0, 'Tooley 15.8 liệt kê thêm IRS, đo cao vô tuyến và GPWS (GPWS có quyền ưu tiên trên TCAS).', 'Tooley 15.8 also lists the IRS, the radio altimeter and the GPWS (GPWS overrides TCAS).', 'TCAS: cảm biến càng', 'TCAS: gear sensor')
X('test', 1, 'Thiết bị thử tự động (ATE) là:', 'Automatic test equipment (ATE) is:', [('thiết bị thử mặt đất chuyên dụng thực hiện nhiều phép thử và kiểm tra chức năng trên một LRU hoặc bảng mạch in', 'a dedicated ground test instrument that runs many tests and functional checks on an LRU or printed circuit card'), ('bộ tự kiểm tra gắn sẵn trên máy bay', 'a self-test built into the aircraft'), ('một dạng hiển thị buồng lái', 'a kind of cockpit display')], 0, 'ATE đắt nên thường chỉ OEM và xưởng được cấp phép dùng (Tooley 15.9).', 'ATE is expensive so it is usually used only by OEMs and licensed repairers (Tooley 15.9).', 'ATE', 'ATE')
X('test', 1, 'BITE chủ yếu là:', 'BITE is primarily:', [('tính năng tự kiểm tra gắn sẵn trên thiết bị bay như một chỉ báo lỗi tích hợp', 'a self-test feature built into airborne equipment as an integral fault indicator'), ('thiết bị thử đặt trong xưởng', 'a test set kept in the workshop'), ('một loại ăng ten', 'a kind of antenna')], 0, 'BITE thường thiết kế theo kiểu thử dòng tín hiệu (Tooley 15.10).', 'BITE is usually a signal-flow type test (Tooley 15.10).', 'BITE', 'BITE')
X('test', 2, 'Chức năng nào sau đây KHÔNG thuộc khả năng của BITE theo Tooley?', 'Which of the following is NOT a BITE capability listed by Tooley?', [('tự sửa chữa phần cứng bị hỏng', 'repairing failed hardware by itself'), ('báo động đạt/không đạt (go/no-go)', 'go/no-go alarms'), ('cô lập hỏng hóc mô-đun hoặc cụm con', 'module and/or subassembly failure isolation'), ('trạng thái hoạt động suy giảm', 'degraded operation status')], 0, 'Danh sách của Tooley gồm giám sát thời gian thực, hiển thị liên tục, cô lập hỏng, xác minh trạng thái, báo động, hiển thị định lượng, phần trăm suy giảm.', 'Tooley\'s list covers real-time monitoring, continuous display, failure isolation, status verification, alarms, quantitative displays and percentage of deterioration.', 'Khả năng BITE', 'BITE capabilities')
X('test', 2, 'Sau khi tổ lái ghi nhận thông báo hỏng hóc của ECAM, nhân viên bảo dưỡng có thể theo dõi bằng cách dùng:', 'After the flight crew records an ECAM failure message, maintenance staff can follow it up using:', [('các chức năng thử trên bảng bảo dưỡng ở buồng lái và BITE trên từng máy tính', 'the test facilities on the cockpit maintenance panel and the BITE on each computer'), ('chỉ ATE ở xưởng của hãng chế tạo', 'only the manufacturer\'s workshop ATE'), ('radar thời tiết', 'the weather radar')], 0, 'Tooley 15.10.', 'Tooley 15.10.', 'ECAM và bảo dưỡng', 'ECAM and maintenance')
for tf in ((True, 'Hệ thống FMS có thể là "lắp đôi" (dual fit): hai hệ thống cùng tính vị trí và đối chiếu chéo.', 'An FMS can be a "dual fit": each system computes the position and cross-checks the other.', 'Tooley 15.5: đối chiếu chéo bảo đảm độ chính xác.', 'Tooley 15.5: cross-checks ensure accuracy.'),
           (False, 'GPS không phụ thuộc vào đồng hồ chính xác của vệ tinh.', 'GPS does not depend on the precise clocks of the satellites.', 'Độ chính xác dựa trên đồng hồ nguyên tử trên mỗi vệ tinh (Tooley 15.6).', 'The accuracy rests on the atomic clocks in each satellite (Tooley 15.6).'),
           (True, 'IRS dùng con quay laser hoặc quang học trong thiết bị hiện đại vì ít bộ phận chuyển động nên tin cậy hơn.', 'Modern IRS equipment uses laser or optical gyros because few moving parts make them more reliable.', 'Tooley 15.7.', 'Tooley 15.7.'),
           (False, 'TCAS đưa ra hướng dẫn tránh va chạm cả theo chiều ngang lẫn chiều thẳng đứng.', 'TCAS gives collision-avoidance guidance both laterally and vertically.', 'Chỉ chiều thẳng đứng (Tooley 15.8).', 'Vertical only (Tooley 15.8).'),
           (True, 'Nếu máy bay kia cũng dùng TCAS II thì các lệnh cao độ được phối hợp để hai máy bay không cùng "thoát" theo một hướng.', 'If the other aircraft also uses TCAS II the pitch commands are coordinated so that both do not escape in the same direction.', 'Tooley 15.8.', 'Tooley 15.8.'),
           (False, 'ATE là tính năng tự kiểm tra gắn sẵn trên máy bay.', 'ATE is a self-test feature built into the aircraft.', 'ATE là thiết bị thử mặt đất; tính năng tự kiểm tra gắn sẵn là BITE (Tooley 15.9, 15.10).', 'ATE is ground test equipment; the built-in self-test is BITE (Tooley 15.9, 15.10).')):
    B.TF('test' if 'ATE' in tf[2] else 'fms' if 'FMS' in tf[2] else 'gps' if 'GPS' in tf[2] else 'irs' if 'IRS' in tf[2] else 'tcas', 1, tf[1], tf[2], tf[0], tf[3], tf[4], 'Đúng/Sai theo Tooley 15.4 đến 15.10', 'True/False after Tooley 15.4 to 15.10')
# ---------- tu luan ----------
t = A.tau(8, 480); B.E('tcas', 3, 'Máy bay của bạn bay với tốc độ 240 kt, máy bay lạ bay ngược chiều trên cùng đường với tốc độ 240 kt, hiện cách 8 NM. (a) Tốc độ tiếp cận? (b) Thời gian tới điểm tiếp cận gần nhất? (c) Dữ liệu nào TCAS không cần để tính cảnh báo này? (d) Nếu TCAS đưa RA, phi công phải làm gì?',
  'Your aircraft flies at 240 kt and an intruder flies head-on along the same track at 240 kt, now 8 NM away. (a) The closure rate? (b) The time to the closest point of approach? (c) Which data does TCAS not need to compute this alert? (d) If TCAS issues an RA, what must the pilot do?',
  f'(a) 240 + 240 = 480 kt. (b) $\\tau=8/480$ h = {t:g} s. (c) Không cần phương vị hay hướng bay, chỉ cần khoảng cách và tốc độ tiếp cận (Tooley 15.8). (d) Tắt lái tự động, bay lệnh cao độ bằng tay, bỏ qua flight director và khuyến cáo ATC nếu cần; lệnh RA có ưu tiên cao nhất.',
  f'(a) 240 + 240 = 480 kt. (b) $\\tau=8/480$ h = {t:g} s. (c) Neither bearing nor heading is needed, only distance and closure rate (Tooley 15.8). (d) Disengage the autopilot, fly the pitch command manually, and ignore flight-director and ATC advisories if necessary; the RA has the highest priority.', 'Tính toán TCAS', 'TCAS calculation')
B.E('irs', 3, 'Một máy bay có gia tốc kế đo 1,5 m/s² dọc đường bay trong 40 s từ trạng thái nghỉ. (a) Vận tốc? (b) Quãng đường? (c) Nếu dữ liệu gia tốc có sai số hằng 0,01 m/s², sai số vận tốc và quãng đường sau 40 s là bao nhiêu? (d) Vì sao điều này giải thích nhu cầu khởi tạo chính xác và dùng GPS để bổ trợ?',
  'An accelerometer along the track reads 1.5 m/s² for 40 s from rest. (a) The velocity? (b) The distance? (c) If the acceleration data has a constant error of 0.01 m/s², what are the velocity and distance errors after 40 s? (d) Why does this explain the need for accurate initialisation and GPS aiding?',
  f'(a) $v=at={A.speed(1.5, 40):g}$ m/s. (b) $s=\\tfrac12at^2={A.dist(1.5, 40):g}$ m. (c) Sai số vận tốc $0{{,}}01\\times40={A.speed(0.01, 40):g}$ m/s; sai số quãng đường $\\tfrac12\\times0{{,}}01\\times40^2={A.dist(0.01, 40):g}$ m, và tăng theo $t^2$. (d) Sai số tích luỹ theo thời gian, nên mốc ban đầu phải chính xác (Tooley 15.7); GPS cung cấp thông tin bổ sung (không bắt buộc về vận hành).',
  f'(a) $v=at={A.speed(1.5, 40):g}$ m/s. (b) $s=\\tfrac12at^2={A.dist(1.5, 40):g}$ m. (c) Velocity error $0.01\\times40={A.speed(0.01, 40):g}$ m/s; distance error $\\tfrac12\\times0.01\\times40^2={A.dist(0.01, 40):g}$ m, growing with $t^2$. (d) Errors accumulate with time, so the initial datum must be accurate (Tooley 15.7); GPS supplies additional information (not operationally necessary).', 'Sai số tích phân IRS', 'IRS integration error')
B.E('gps', 3, 'GPS: (a) Đổi độ cao quỹ đạo 20 200 km sang hải lý. (b) Tính chu kỳ quỹ đạo tròn ở độ cao đó (bán kính Trái Đất 6 371 km, $\\mu=3{,}986\\times10^{14}$ m³/s²) và so với 12 giờ của Tooley. (c) Mã C/A 1,023 MHz lặp mỗi 1 ms gồm bao nhiêu chip? (d) Nêu ba đoạn của GPS.',
  'GPS: (a) Convert the orbit height of 20,200 km to nautical miles. (b) Compute the period of a circular orbit at that height (Earth radius 6,371 km, $\\mu=3.986\\times10^{14}$ m³/s²) and compare it with Tooley\'s 12 hours. (c) How many chips does the 1.023 MHz C/A code, repeating every 1 ms, contain? (d) Name the three GPS segments.',
  f'(a) 20 200 / 1,852 = {A.km_to_nm(20200):,.0f} NM (Tooley làm tròn 10 900). (b) $r=26571$ km; $T=2\\pi\\sqrt{{r^3/\\mu}}$ = {A.orbit_period_a(20200):,.0f} s = {A.orbit_period_a(20200) / 3600:.2f} giờ ≈ 12 giờ: khớp. (c) $1{{,}}023\\times10^6\\times10^{{-3}}$ = 1 023 chip. (d) Không gian, người dùng, điều khiển.',
  f'(a) 20,200 / 1.852 = {A.km_to_nm(20200):,.0f} NM (Tooley rounds to 10,900). (b) $r=26571$ km; $T=2\\pi\\sqrt{{r^3/\\mu}}$ = {A.orbit_period_a(20200):,.0f} s = {A.orbit_period_a(20200) / 3600:.2f} hours ≈ 12 hours: it agrees. (c) $1.023\\times10^6\\times10^{{-3}}$ = 1,023 chips. (d) Space, user and control.', 'Tính toán GPS', 'GPS calculation')
if __name__ == '__main__': B.write('m12')
